"""Technical-work simulations: a hands-on job done step by step, where one option is the technically correct one and the others fail for a stated technical reason.

Two of them: building a regulated LED circuit on a breadboard, and carrying out an appendicectomy (as a surgical resident). Unlike the career simulations
there is no normal day / crisis pair and no partial credit: a wrong option stops the job at that step (`fails=True`) and the report says exactly what went wrong
and what the correct step was. The narrator describes each situation and asks what you want to do.

Educational only. The circuit values are standard hobby-electronics practice. The operation is a fictional patient in a simplified, step-by-step version of an
open appendicectomy; it is not medical training and gives no clinical advice."""
from __future__ import annotations

from .engine import Choice as C, Ending, Meter, Round, Scenario

_GOOD = {"problem_solving": 2, "risk_management": 1, "decision_making": 1}
_BAD = {"problem_solving": -1, "risk_management": -2}


def _step(id, title, clock, brief, question, facts, scene, good, bad1, bad2, gain):
    """Each option: (label, summary, consequence, lesson). The first is the one that works; the other two fail."""
    return Round(id, title, clock, "simulation", brief, question, tuple(facts), (
        C(f"{id}_strong", good[0], good[1], good[2], "strong", {"progress": gain}, (), skills=_GOOD, lesson=good[3]),
        C(f"{id}_mixed", bad1[0], bad1[1], bad1[2], "weak", {}, (), skills=_BAD, lesson=bad1[3], fails=True),
        C(f"{id}_weak", bad2[0], bad2[1], bad2[2], "weak", {}, (), skills=_BAD, lesson=bad2[3], fails=True),
    ), "", scene)


def _endings(ok_title, ok_text, fail_title, fail_text):
    return (Ending("failed", fail_title, fail_text, (("flag", "failed"),), "bad"), Ending("success", ok_title, ok_text, (), "good"))


